const d = $input.first().json;
const ev = d.events || [];
const count = (type, token) => ev.filter(e => e.type === type && (!token || e.token === token)).length;
const short = a => a ? a.slice(0, 6) + '...' + a.slice(-4) : '';
const scan = a => 'https://basescan.org/address/' + a;
const lines = [];
let flagged = 0;
for (const t of d.tokens || []) {
  const b = count('bundle', t.address), s = count('sandwich', t.address), sn = count('sniper', t.address), w = count('whale', t.address), z = count('zero_value_transfer', t.address);
  flagged += b + s + sn;
  lines.push(`${t.symbol} (${t.label})  ${t.address}`);
  lines.push(`  Last 24h: ${t.trades_period} trades (${t.buys_period} buys, ${t.sells_period} sells) by ${t.traders_period} wallets`);
  lines.push(`  All time: ${t.trades_total} trades by ${t.traders_total} wallets`);
  lines.push(`  Flagged in last 24h: ${sn} sniper buys, ${b} bundles, ${s} sandwiches, ${w} whale trades, ${z} zero-value transfers`);
  lines.push(`  All time: ${t.snipers} sniper wallets, ${t.fresh_wallet_buyers} buyers with wallets under 24h old`);
  for (const f of t.top_funders || []) lines.push(`  Funding cluster: ${f.wallets} buyer wallets were first funded by ${short(f.funder)}  ${scan(f.funder)}`);
  lines.push('');
}
const priority = ['copycat', 'sandwich', 'sniper', 'bundle', 'whale', 'zero_value_transfer', 'first_trade'];
const notable = [];
for (const p of priority) notable.push(...ev.filter(e => e.type === p).slice(0, p === 'whale' ? 5 : 8));
if (notable.length) {
  lines.push('NOTABLE (newest examples, max 8 per type)');
  for (const e of notable) {
    const x = e.detail || {};
    let msg = '';
    if (e.type === 'copycat') msg = `Copycat token ${x.symbol} "${x.name}" ${x.url || ''}`;
    else if (e.type === 'sandwich') msg = `Sandwich: ${short(x.attacker)} bought before and sold after ${short(x.victim)} in block ${x.block}  https://basescan.org/tx/${e.tx}`;
    else if (e.type === 'sniper') msg = `Sniper: ${short(e.wallet)} bought ${x.blocks_after_deploy} blocks after deploy, paid ${x.paid} ETH  ${scan(e.wallet)}`;
    else if (e.type === 'bundle') msg = `Bundle: ${(x.wallets || []).length} wallets bought back-to-back in block ${x.block}, each paying about ${(x.paid_each || [])[0]} ETH`;
    else if (e.type === 'whale') msg = `Whale ${x.side}: ${short(e.wallet)} moved ${Number(x.amount).toLocaleString()} tokens for ${x.paid} ETH`;
    else if (e.type === 'zero_value_transfer') msg = `Zero-value transfer to ${short(e.wallet)} from ${short(x.from)} (address poisoning pattern)  https://basescan.org/tx/${e.tx}`;
    else msg = `${e.type} ${short(e.wallet)}`;
    lines.push('  ' + msg);
  }
  lines.push('');
}
const cc = d.copycats || [];
if (cc.length) { lines.push('NEW COPYCATS'); for (const c of cc) lines.push(`  ${c.symbol} "${c.name}" ${c.address} ${c.url || ''}`); lines.push(''); }
lines.push('Raw data: Supabase project "Deep research", schema flag.');
const total = (d.tokens || []).reduce((a, t) => a + Number(t.trades_period || 0), 0);
return [{ json: { subject: `$FLAG tracker daily: ${total} trades, ${flagged} bot patterns, ${cc.length} new copycats`, body: lines.join('\n') } }];
